function drawEmbankments(ctx) {
  for (let lane = 0; lane < LANE_COUNT; lane++) {
    /* 每段距离画护坡梯形 */
    for (let d = 0; d < G.maxDist; d += 80) {
      const s0 = worldToScreen(d);
      const s1 = worldToScreen(d + 80);
      if (s0.y < G.vanishY || s1.y > G.H + 20) continue;

      const sc0 = Math.max(0.1, s0.scale);
      const sc1 = Math.max(0.1, s1.scale);

      const lx0 = laneX(lane, d);
      const lx1 = laneX(lane, d + 80);

      /* 左侧护坡 */
      const lOuter0 = lx0 - 22 * sc0, lOuter1 = lx1 - 22 * sc1;
      ctx.fillStyle = '#6b8e5a';
      ctx.beginPath();
      ctx.moveTo(lOuter0, s0.y);
      ctx.lineTo(lOuter1, s1.y);
      ctx.lineTo(lx1 - 12 * sc1, s1.y);
      ctx.lineTo(lx0 - 12 * sc0, s0.y);
      ctx.closePath();
      ctx.fill();
      /* 坡顶亮线 */
      ctx.strokeStyle = '#7a9e68';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(lOuter0, s0.y);
      ctx.lineTo(lOuter1, s1.y);
      ctx.stroke();

      /* 右侧护坡 */
      const rOuter0 = lx0 + 22 * sc0, rOuter1 = lx1 + 22 * sc1;
      ctx.fillStyle = '#6b8e5a';
      ctx.beginPath();
      ctx.moveTo(lx0 + 12 * sc0, s0.y);
      ctx.lineTo(lx1 + 12 * sc1, s1.y);
      ctx.lineTo(rOuter1, s1.y);
