function drawTracksideScenery(ctx) {
  const poleInterval = 180; // 电杆间距（世界坐标）

  for (let lane = 0; lane < LANE_COUNT; lane++) {
    for (let d = poleInterval; d < G.maxDist; d += poleInterval) {
      const s = worldToScreen(d);
      if (s.y < G.vanishY + 10 || s.y > G.H + 40) continue;

      const lx = laneX(lane, d);
      const sc = Math.max(0.08, s.scale);
      const poleH = 35 * sc;
      const poleW = 3 * sc;

      /* 左侧电杆 */
      const lpx = lx - 28 * sc;
      ctx.fillStyle = '#5a4a3a';
      ctx.fillRect(lpx - poleW/2, s.y - poleH, poleW, poleH);
      /* 杆顶横梁 */
      ctx.fillRect(lpx - 6*sc, s.y - poleH, poleW * 4, poleW);
      /* 瓷瓶 */
      ctx.fillStyle = '#ddd';
      ctx.fillRect(lpx - 5*sc, s.y - poleH - 2*sc, 2*sc, 3*sc);
      ctx.fillRect(lpx + 2*sc, s.y - poleH - 2*sc, 2*sc, 3*sc);

      /* 右侧电杆 */
      const rpx = lx + 28 * sc;
      ctx.fillStyle = '#5a4a3a';
      ctx.fillRect(rpx - poleW/2, s.y - poleH, poleW, poleH);
      ctx.fillRect(rpx - 6*sc, s.y - poleH, poleW * 4, poleW);
      ctx.fillStyle = '#ddd';
      ctx.fillRect(rpx - 5*sc, s.y - poleH - 2*sc, 2*sc, 3*sc);
      ctx.fillRect(rpx + 2*sc, s.y - poleH - 2*sc, 2*sc, 3*sc);
    }

    /* 灌木丛（不同间距避免与电杆重叠） */
    for (let d = 60; d < G.maxDist; d += 110) {
      const s = worldToScreen(d);
      if (s.y < G.vanishY + 20 || s.y > G.H + 30) continue;

      const lx = laneX(lane, d);
      const sc = Math.max(0.08, s.scale);
      const bushR = 5 * sc;

      /* 随机左右各放灌木 */
      if ((d + lane * 73) % 3 !== 0) {
        const bx = lx + (d % 2 === 0 ? -22 : 22) * sc;
        ctx.fillStyle = '#4a7a3a';
        ctx.beginPath();
        ctx.arc(bx, s.y, bushR, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#5a8a4a';
        ctx.beginPath();
        ctx.arc(bx + 2*sc, s.y - 1*sc, bushR * 0.7, 0, Math.PI * 2);
        ctx.fill();
      }
    }
  }
}

