    ctx.drawImage(G.offscreen.clouds, cloudOffset, 0, G.W, G.offscreen.clouds.height, 0, 0, G.W, G.offscreen.clouds.height);
  } else {
    const w1 = G.offscreen.clouds.width - cloudOffset;
    ctx.drawImage(G.offscreen.clouds, cloudOffset, 0, w1, G.offscreen.clouds.height, 0, 0, w1, G.offscreen.clouds.height);
    ctx.drawImage(G.offscreen.clouds, 0, 0, G.W - w1, G.offscreen.clouds.height, w1, 0, G.W - w1, G.offscreen.clouds.height);
  }
  /* 远山（最慢视差） */
  const mtnOffset = (G.distance * PARALLAX_MOUNTAIN) % G.offscreen.mountains.width;
  if (mtnOffset + G.W <= G.offscreen.mountains.width) {
    ctx.drawImage(G.offscreen.mountains, mtnOffset, 0, G.W, G.offscreen.mountains.height, 0, G.vanishY - G.offscreen.mountains.height + 60, G.W, G.offscreen.mountains.height);
  } else {
    const w1 = G.offscreen.mountains.width - mtnOffset;
    ctx.drawImage(G.offscreen.mountains, mtnOffset, 0, w1, G.offscreen.mountains.height, 0, G.vanishY - G.offscreen.mountains.height + 60, w1, G.offscreen.mountains.height);
