  }
  /* 城市天际线（远景） */
  const cityOffset = (G.distance * PARALLAX_FAR) % (G.W * 3);
  if (cityOffset + G.W <= G.offscreen.city.width) {
    ctx.drawImage(G.offscreen.city, cityOffset, 0, G.W, G.H*0.25, 0, G.vanishY - 30, G.W, G.H*0.25);
  } else {
    const w1 = G.offscreen.city.width - cityOffset;
    ctx.drawImage(G.offscreen.city, cityOffset, 0, w1, G.H*0.25, 0, G.vanishY - 30, w1, G.H*0.25);
    ctx.drawImage(G.offscreen.city, 0, 0, G.W - w1, G.H*0.25, w1, G.vanishY - 30, G.W - w1, G.H*0.25);
  }
  /* 近景建筑 */
  const nearOffset = (G.distance * PARALLAX_NEAR) % (G.W * 2);
  if (nearOffset + G.W <= G.offscreen.nearCity.width) {
    ctx.drawImage(G.offscreen.nearCity, nearOffset, 0, G.W, G.H*0.35, 0, G.vanishY + 10, G.W, G.H*0.35);
  } else {
    const w1 = G.offscreen.nearCity.width - nearOffset;
    ctx.drawImage(G.offscreen.nearCity, nearOffset, 0, w1, G.H*0.35, 0, G.vanishY + 10, w1, G.H*0.35);
    ctx.drawImage(G.offscreen.nearCity, 0, 0, G.W - w1, G.H*0.35, w1, G.vanishY + 10, G.W - w1, G.H*0.35);
  }
  drawGround(ctx);
  drawTracks(ctx);
}

