function update() {
  if (G.state !== 'playing') return;
  const p = G.player;

  updateSpeedScore();
  updateTimers();
  p.lane = lerp(p.lane, p.targetLane, LANE_SWITCH_SPEED);
  updatePlayerState(p);
  updateAnimation(p);
  updateObstacles(p);
  updateTrains(p);
  updateCoins(p);
  updateParticles();
  updateSpawning();
  updatePowerups(p);
  updateFinalize(p);
  updatePopups();
}

function updateSpeedScore() {
  G.speed = Math.min(G.speed + SPEED_INC, MAX_SPEED);
  G.distance += G.speed * DISTANCE_PER_FRAME;
  G.score = Math.floor(G.distance * DISTANCE_SCORE * G.player.scoreMultiplier) + G.coinScore;
}

function updateTimers() {
  if (G.invincible > 0) G.invincible--;
  if (G.shakeDuration > 0) {
    G.shakeDuration--;
    G.shakeX *= 0.8;
    G.shakeY *= 0.8;
  } else {
    G.shakeX = 0; G.shakeY = 0;
  }
  if (G.flashAlpha > 0) G.flashAlpha -= FLASH_FADE;
}

function updatePlayerState(p) {
  if (p.state === STATE_JUMP) {
    p.stateTimer--;
    if (p.stateTimer <= 0) {
      p.state = STATE_RUN; p.stateTimer = 0;
      burstParticles(p.x, G.groundY + 8, 8, 30, 4, 2, [10, 20], ['rgba(180,160,140,0.6)','rgba(200,180,160,0.3)']);
    }
  } else if (p.state === STATE_SLIDE) {
    p.stateTimer--;
    if (p.stateTimer <= 0) { p.state = STATE_RUN; p.stateTimer = 0; }
  } else if (p.state === STATE_HIT) {
    p.stateTimer--;
    if (p.stateTimer <= 0) { p.state = STATE_RUN; }
  }
  if (p.celebrateTimer > 0) {
    p.celebrateTimer--;
    if (p.celebrateTimer <= 0) p.celebrateType = null;
  }
}

function updateAnimation(p) {
  p.animTimer++;
  if (p.animTimer > ANIM_INTERVAL) {
    p.animTimer = 0;
    p.animFrame = (p.animFrame + 1) % 4;
  }
}

function updateTrains(p) {
