function renderEntities(ctx) {
  const entities = [];
  for (let i = 0; i < G.obstacles.length; i++) {
    const o = G.obstacles[i];
    if (!o.active) continue;
    entities.push({ type:'obstacle', obj:o, dist:o.dist, lane:o.lane });
  }
  for (let i = 0; i < G.trains.length; i++) {
    const t = G.trains[i];
    if (!t.active) continue;
    entities.push({ type:'train', obj:t, dist:t.dist, lane:t.lane });
  }
  for (let i = 0; i < G.coins.length; i++) {
    const c = G.coins[i];
    if (!c.active || c.collected) continue;
    entities.push({ type:'coin', obj:c, dist:c.dist, lane:c.lane });
  }
  for (let i = 0; i < G.powerups.length; i++) {
    const pu = G.powerups[i];
    if (!pu.active || pu.collected) continue;
    entities.push({ type:'powerup', obj:pu, dist:pu.dist, lane:pu.lane });
  }
  entities.sort((a, b) => b.dist - a.dist);
  const frontEntities = entities.filter(e => e.dist > 0);
  const behindEntities = entities.filter(e => e.dist <= 0);

  frontEntities.forEach(e => {
    const s = worldToScreen(e.dist);
    if (s.y < G.vanishY - 20 || s.y > G.H + 60) return;
    const sx = laneX(e.lane, e.dist);
    if (e.type === 'obstacle') drawObstacle(ctx, e.obj, sx, s.y, s.scale);
    else if (e.type === 'train') drawTrain(ctx, e.obj, e.lane, e.dist, sx, s.y, s.scale);
    else if (e.type === 'coin') drawCoin(ctx, e.obj, sx, s.y, s.scale);
    else if (e.type === 'powerup') drawPowerup(ctx, e.obj, sx, s.y, s.scale);
  });
  drawPlayer(ctx);
  behindEntities.forEach(e => {
    const s = worldToScreen(e.dist);
    if (s.y < G.vanishY - 20 || s.y > G.H + 60) return;
    const sx = laneX(e.lane, e.dist);
    if (e.type === 'obstacle') drawObstacle(ctx, e.obj, sx, s.y, s.scale);
    else if (e.type === 'train') drawTrain(ctx, e.obj, e.lane, e.dist, sx, s.y, s.scale);
    else if (e.type === 'coin') drawCoin(ctx, e.obj, sx, s.y, s.scale);
    else if (e.type === 'powerup') drawPowerup(ctx, e.obj, sx, s.y, s.scale);
  });
}

